import Page7 from './pages/Page7.jsx';
import Page8 from './pages/Page8.jsx';
import Page9 from './pages/Page9.jsx';
import Page10 from './pages/Page10.jsx';
import Page11 from './pages/Page11.jsx';
import Page12 from './pages/Page12.jsx';
const pages={"demo-sneaker-store-1":Page0,"demo-sneaker-store-1-about":Page1,"demo-sneaker-store-1-account":Page2,"demo-sneaker-store-1-blog":Page3,"demo-sneaker-store-1-brands":Page4,"demo-sneaker-store-1-cart":Page5,"demo-sneaker-store-1-checkout":Page6,"demo-sneaker-store-1-launches":Page7,"demo-sneaker-store-1-lookbook":Page8,"demo-sneaker-store-1-order-complete":Page9,"demo-sneaker-store-1-product":Page10,"demo-sneaker-store-1-shop":Page11,"demo-sneaker-store-1-store":Page12};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-sneaker-store-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-sneaker-store-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

